79: namespace {
80:     class PipeWriter : public ErrorLogger {
81:     public:
82:         enum PipeSignal : std::uint8_t {REPORT_OUT='1',REPORT_ERROR='2',REPORT_SUPPR_INLINE='3',REPORT_SUPPR='4',CHILD_END='5',REPORT_METRIC='6',REPORT_TIMER='7'};
83: 
84:         explicit PipeWriter(int pipe, bool debug) : mWpipe(pipe), mDebug(debug) {}
85: 
86:         void reportOut(const std::string &outmsg, Color c) override {
87:             writeToPipe(REPORT_OUT, static_cast<char>(c) + outmsg);
88:         }
89: 
90:         void reportErr(const ErrorMessage &msg) override {
91:             writeToPipe(REPORT_ERROR, msg.serialize());
92:         }
93: 
94:         void writeSuppr(const SuppressionList &supprs) const {
95:             for (const auto& suppr : supprs.getSuppressions())
96:             {
97:                 if (suppr.isInline)
98:                     writeToPipe(REPORT_SUPPR_INLINE, suppressionToString(suppr));
99:                 else if (suppr.checked)
100:                     writeToPipe(REPORT_SUPPR, suppressionToString(suppr));
101:             }
102:         }
103: 
104:         void reportMetric(const std::string &metric) override {
105:             writeToPipe(REPORT_METRIC, metric);
106:         }
107: 
108:         void writeTimer(const TimerResults* timerResults) const {
109:             if (!timerResults)
110:                 return;
111: 
112:             for (const auto& entry : timerResults->getResults())
113:             {
114:                 for (const auto& d : entry.second) {
115:                     writeToPipe(REPORT_TIMER, entry.first + ";" + std::to_string(d.count()));
116:                 }
117:             }
118:         }
119: 
120:         void writeEnd(const std::string& str) const {
121:             writeToPipe(CHILD_END, str);
122:         }
123: 
124:     private:
125:         static std::string suppressionToString(const SuppressionList::Suppression &suppr)
126:         {
127:             std::string suppr_str = suppr.toString();
128:             suppr_str += ";";
129:             suppr_str += std::to_string(suppr.column);
130:             suppr_str += ";";
131:             suppr_str += suppr.checked ? "1" : "0";
132:             suppr_str += ";";
133:             suppr_str += suppr.matched ? "1" : "0";
134:             suppr_str += ";";
135:             suppr_str += suppr.extraComment;
136:             return suppr_str;
137:         }
138: 
139:         // TODO: how to log file name in error?
140:         void writeToPipeInternal(PipeSignal type, const void* data, std::size_t to_write) const
141:         {
142:             const ssize_t bytes_written = write(mWpipe, data, to_write);
143:             if (bytes_written <= 0) {
144:                 const int err = errno;
145:                 std::cerr << "#### ThreadExecutor::writeToPipeInternal() error for type " << static_cast<unsigned char>(type) << ": " << std::strerror(err) << std::endl;
146:                 std::exit(EXIT_FAILURE);
147:             }
148:             // TODO: write until everything is written
149:             if (bytes_written != to_write) {
150:                 std::cerr << "#### ThreadExecutor::writeToPipeInternal() error for type " << static_cast<unsigned char>(type) << ": insufficient data written (expected: " << to_write << " / got: " << bytes_written << ")" << std::endl;
151:                 std::exit(EXIT_FAILURE);
152:             }
153:         }
154: 
155:         void writeToPipe(PipeSignal type, const std::string &data) const
156:         {
157:             if (mDebug)
158:                 std::cout << "writeToPipe - " << static_cast<char>(type) << " - " << data << std::endl;
159: 
160:             {
161:                 const auto t = static_cast<char>(type);
162:                 writeToPipeInternal(type, &t, 1);
163:             }
164: 
165:             const auto len = static_cast<unsigned int>(data.length());
166:             {
167:                 static constexpr std::size_t l_size = sizeof(unsigned int);
168:                 writeToPipeInternal(type, &len, l_size);
169:             }
170: 
171:             if (len > 0) // TODO: unexpected - write a warning?
172:                 writeToPipeInternal(type, data.c_str(), len);
173:         }
174: 
175:         const int mWpipe;
176:         const bool mDebug;
177:     };
