90:             err == ERROR_PATH_NOT_FOUND)   // the given search path does not exist
91:         {
92:             return "";
93:         }
94:         return "finding files failed. Search pattern: '" + searchPattern + "'. (error: " + std::to_string(err) + ")";
95:     }
96:     std::unique_ptr<void, decltype(&FindClose)> hFind_deleter(hFind, FindClose);
97: 
98:     do {
99:         if (ffd.cFileName[0] != '.' && ffd.cFileName[0] != '\0')
100:         {
