229:     }
230:     std::unique_ptr<DIR, closedir_deleter> dir_deleter(dir);
231: 
232:     std::string new_path = path;
233:     new_path += '/';
234: 
235:     while (const dirent* dir_result = readdir(dir)) {
236:         if ((std::strcmp(dir_result->d_name, ".") == 0) ||
237:             (std::strcmp(dir_result->d_name, "..") == 0))
238:             continue;
