254:                     }
255:                 }
256:                 else if (debug)
257:                 {
258:                     std::cout << "ignored path: " << new_path << std::endl;
259:                 }
260:             }
261:         } else {
262:             Standards::Language lang = Standards::Language::None;
263:             if (Path::acceptFile(new_path, extra, &lang)) {
264:                 if (!ignored.match(new_path))
265:                 {
266:                     if (stat(new_path.c_str(), &file_stat) == -1) {
267:                         const int err = errno;
268:                         return "could not stat file '" + new_path + "' (errno: " + std::to_string(err) + ")";
