634: void StdLogger::reportErr(const ErrorMessage &msg)
635: {
636:     if (msg.severity == Severity::internal && (msg.id == "logChecker" || endsWith(msg.id, "-logChecker"))) {
637:         const std::string& checker = msg.shortMessage();
638:         mActiveCheckers.emplace(checker);
639:         return;
640:     }
641: 
642:     if (msg.severity == Severity::internal && msg.id == "ctuinfo") {
643:         mCtuInfo += msg.shortMessage() + "\n";
644:         return;
645:     }
646: 
647:     if (ErrorLogger::isCriticalErrorId(msg.id) && mCriticalErrors.find(msg.id) == std::string::npos) {
648:         if (!mCriticalErrors.empty())
649:             mCriticalErrors += ", ";
650:         mCriticalErrors += msg.id;
651:         if (msg.severity == Severity::internal)
652:             mCriticalErrors += " (suppressed)";
653:     }
654: 
655:     if (msg.severity == Severity::internal)
656:         return;
657: 
658:     ErrorMessage msgCopy = msg;
659:     msgCopy.guideline = getGuideline(msgCopy.id, mSettings.reportType,
660:                                      mGuidelineMapping, msgCopy.severity);
661:     msgCopy.classification = getClassification(msgCopy.guideline, mSettings.reportType);
662: 
663:     // TODO: there should be no need for verbose and default messages here
664:     const std::string msgStr =
665:         msgCopy.toString(mSettings.verbose, mSettings.templateFormat, mSettings.templateLocation);
666: 
667:     // Alert only about unique errors
668:     if (!mSettings.emitDuplicates && !mShownErrors.insert(msgStr).second)
669:         return;
670: 
671:     if (mSettings.outputFormat == Settings::OutputFormat::sarif) {
672:         mSarifReport.addFinding(std::move(msgCopy));
673:     } else if (mSettings.outputFormat == Settings::OutputFormat::xml) {
674:         reportErr(msgCopy.toXML());
675:     } else {
676:         reportErr(msgStr);
677:     }
678: }
