160:     class PcreRegex : public Regex
161:     {
162:     public:
163:         explicit PcreRegex(std::string pattern)
164:             : mPattern(std::move(pattern))
165:         {}
166: 
167:         ~PcreRegex() override
168:         {
169:             if (mExtra) {
170:                 pcre_free_study(mExtra);
171:                 mExtra = nullptr;
172:             }
173:             if (mRe) {
174:                 pcre_free(mRe);
175:                 mRe = nullptr;
176:             }
177:         }
178: 
179:         std::string compile();
180:         std::string match(const std::string& str, const MatchFn& matchFn) const override;
181: 
182:         Engine engine() const override {
183:             return Engine::Pcre;
184:         }
185: 
186:     private:
187:         std::string mPattern;
188:         pcre* mRe{};
189:         pcre_extra* mExtra{};
190:     };
191: 
192:     std::string PcreRegex::compile()
193:     {
194:         if (mRe)
195:             return "regular expression has already been compiled";
196: 
197:         const char *pcreCompileErrorStr = nullptr;
198:         int erroffset = 0;
199:         pcre * const re = pcre_compile(mPattern.c_str(),0,&pcreCompileErrorStr,&erroffset,nullptr);
200:         if (!re) {
201:             if (pcreCompileErrorStr)
202:                 return pcreCompileErrorStr;
203:             return "unknown error";
204:         }
205: 
206:         // Optimize the regex, but only if PCRE_CONFIG_JIT is available
207: #ifdef PCRE_CONFIG_JIT
208:         const char *pcreStudyErrorStr = nullptr;
209:         pcre_extra * const pcreExtra = pcre_study(re, PCRE_STUDY_JIT_COMPILE, &pcreStudyErrorStr);
210:         // pcre_study() returns NULL for both errors and when it can not optimize the regex.
211:         // The last argument is how one checks for errors.
212:         // It is NULL if everything works, and points to an error string otherwise.
213:         if (pcreStudyErrorStr) {
214:             // pcre_compile() worked, but pcre_study() returned an error. Free the resources allocated by pcre_compile().
215:             pcre_free(re);
216:             return std::string(pcreStudyErrorStr) + " (pcre_study)";
217:         }
218:         mExtra = pcreExtra;
219: #endif
220: 
221:         mRe = re;
222: 
223:         return "";
224:     }
225: 
226:     std::string PcreRegex::match(const std::string& str, const MatchFn& matchFn) const
227:     {
228:         if (!mRe)
229:             return "regular expression has not been compiled yet";
230: 
231:         int pos = 0;
232:         int ovector[30]= {0};
233:         while (pos < static_cast<int>(str.size())) {
234:             const int pcreExecRet = pcre_exec(mRe, mExtra, str.c_str(), static_cast<int>(str.size()), pos, 0, ovector, 30);
235:             if (pcreExecRet == PCRE_ERROR_NOMATCH)
236:                 return "";
237:             if (pcreExecRet < 0) {
238:                 return pcreErrorCodeToString(pcreExecRet) + " (pos: " + std::to_string(pos) + ")";
239:             }
240:             const auto pos1 = static_cast<unsigned int>(ovector[0]);
241:             const auto pos2 = static_cast<unsigned int>(ovector[1]);
242: 
243:             matchFn(pos1, pos2);
244: 
245:             // jump to the end of the match for the next pcre_exec
246:             pos = static_cast<int>(pos2);
247:         }
248: 
249:         return "";
250:     }
251: }
252: 
253: template<typename T>
254: static T* createAndCompileRegex(std::string pattern, std::string& err)
255: {
256:     T* regex = new T(std::move(pattern));
257:     err = regex->compile();
258:     return regex;
259: }
260: 
261: std::shared_ptr<Regex> Regex::create(std::string pattern, Engine engine, std::string& err)
262: {
263:     Regex* regex = nullptr;
264:     if (engine == Engine::Pcre)
265:         regex = createAndCompileRegex<PcreRegex>(std::move(pattern), err);
266:     else {
267:         err = "unknown regular expression engine";
268:     }
269:     if (!err.empty()) {
270:         delete regex;
271:         return nullptr;
272:     }
273:     return std::shared_ptr<Regex>(regex);
274: }
